function UIFeelingShopRoleNode:Start()
end

function UIFeelingShopRoleNode:Refresh(id, index, clickCb, revertCb)
    self._curCatId = checkNumber(id)
    self._clickCb = clickCb
    self._revertCb = revertCb
    self._ind = checkNumber(index)

    local data = phoneComp:GetCatDataById(id)
    self:FillRole(data)
end

function UIFeelingShopRoleNode:FillRole(data)
    if not data then
        return
    end
    KTool.SetActive(self.GivingNum, true)

    CfUtils.FillText(self.TxtNum, PhoneUtils.GetCatCanGiveGiftNum(data.catId).."/"..PhoneUtils.GetAllGiveGiftNum())

    local isCanGive = PhoneUtils.IsCatCanGiveGift(data.catId)
    --KTool.SetActive(self.LockBg, isCanGive)

    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(data.catId)
    CfUtils.FillImage(self.IconHead, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))
    CfUtils.FillText(self.TxtDialogue, PhoneUtils.GetRoleCurName(data.catId))

    local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(data.catId)
    CfUtils.FillText(self.Text, level)
    CfUtils.FillText(self.TxtCurrent, exp.."/"..PhoneUtils.GetLikabilityLevelUpAllExp(level))
    self.sliderCur.value = checkNumber(exp) / PhoneUtils.GetLikabilityLevelUpAllExp(level)

    local canvas = self.controller.gameObject:GetComponent(typeof(CanvasGroup))
    local isCanGiveGift = PhoneUtils.IsCatCanGiveGift(data.catId)
    if not isCanGiveGift then
        canvas.alpha = 0.3
    else
        canvas.alpha = 1
    end
    
    self:ActiveBtnReset(false)
end

--刷新好感度经验
function UIFeelingShopRoleNode:RefreshLikabilityExp(catId, giftId, packId)
    local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(catId)
    if giftId then
        local giftNum = PhoneUtils.GetPhoneGiftGradeUpNum(giftId)
        self.sliderGift.value = (checkNumber(exp) + giftNum) / PhoneUtils.GetLikabilityLevelUpAllExp(level) 
        CfUtils.FillText(self.TxtIncrease, "+"..giftNum)

        local allNum = giftNum
        if packId then
            allNum = PhoneUtils.GetPhoneGiftAndPackGradeUpNum(giftId, packId)
            self.sliderPack.value = (checkNumber(exp) + allNum) / PhoneUtils.GetLikabilityLevelUpAllExp(level)  
            CfUtils.FillText(self.TxtIncrease, "+"..allNum)
        end

        KTool.SetActive(self.TxtUpgrade, (checkNumber(exp) + allNum) >= PhoneUtils.GetLikabilityLevelUpAllExp(level))
    else
        CfUtils.FillText(self.TxtIncrease, "")
        KTool.SetActive(self.TxtUpgrade, false)
    end
end

function UIFeelingShopRoleNode:PlayAni1()
    local ani = self.Root:GetComponent(typeof(Animator))
    self._co = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds((0.1 * self._ind)))
        self:ActiveRoot()
    end)
end

function UIFeelingShopRoleNode:ActiveRoot()
    KTool.SetActive(self.Root, true)
end

function UIFeelingShopRoleNode:ActiveBtnReset(isTrue)
    KTool.SetActive(self.BtnReset, isTrue)
end

--显示送礼次数
function UIFeelingShopRoleNode:GiveGiftNumAnimator()
    KTool.SetActive(self.GivingNum, false)
    self._giveGiftCo = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(2))
        KTool.SetActive(self.GivingNum, true)
    end)
end

function UIFeelingShopRoleNode:OnSelectCat()
    if self._clickCb then
        self._clickCb()
    end
end

function UIFeelingShopRoleNode:OnBtnReset()
    if self._revertCb then
        self._revertCb()
    end
end

function UIFeelingShopRoleNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingShopRoleNode
